// AI Note Taker background service worker (bundled, non-module)
// Bundled intentionally so Chrome can register the worker without resolving
// additional ES module dependencies at startup.

// Generated by build.mjs. Do not commit real API keys.
globalThis.AI_NOTE_CONFIG = {
  "activeProvider": "assemblyai",
  "fallbackProviders": [
    "assemblyai",
    "deepgram",
    "openai"
  ],
  "keys": {
    "deepgram": "",
    "assemblyai": "f4d7a677c14b49dfa5166085c731e8a7",
    "openai": ""
  },
  "deepgramModel": "nova-3",
  "assemblyaiModel": "universal-3-5-pro",
  "openaiModel": "gpt-4o-mini-transcribe",
  "backendUrl": "http://localhost:4000",
  "clientUrl": "http://localhost:3000"
};

// Offline script normalization for multilingual transcripts.
// Roman / Latin mode preserves existing Latin text and transliterates
// Devanagari (Hindi) and Arabic-derived scripts (including Urdu) into Latin.

const DEV_CONSONANTS = {
  'क':'k','ख':'kh','ग':'g','घ':'gh','ङ':'ng','च':'ch','छ':'chh','ज':'j','झ':'jh','ञ':'ny',
  'ट':'t','ठ':'th','ड':'d','ढ':'dh','ण':'n','त':'t','थ':'th','द':'d','ध':'dh','न':'n',
  'प':'p','फ':'ph','ब':'b','भ':'bh','म':'m','य':'y','र':'r','ल':'l','व':'v',
  'श':'sh','ष':'sh','स':'s','ह':'h','ळ':'l'
};
const DEV_VOWELS = {
  'अ':'a','आ':'aa','इ':'i','ई':'ee','उ':'u','ऊ':'oo','ऋ':'ri','ए':'e','ऐ':'ai','ओ':'o','औ':'au'
};
const DEV_MATRAS = {'ा':'aa','ि':'i','ी':'ee','ु':'u','ू':'oo','ृ':'ri','ॄ':'ree','े':'e','ै':'ai','ो':'o','ौ':'au'};
const DEV_SPECIAL = {
  'ं':'n','ँ':'n','ः':'h','ऽ':'\'', '।':'.','॥':'..','॰':'.'
};
const DEV_NUKTA = {
  'क़':'q','ख़':'kh','ग़':'gh','ज़':'z','ड़':'r','ढ़':'rh','फ़':'f','य़':'y'
};

const URDU = {
  'ا':'a','آ':'aa','أ':'a','إ':'i','ٱ':'a','ب':'b','پ':'p','ت':'t','ٹ':'t','ث':'s','ج':'j','چ':'ch','ح':'h','خ':'kh',
  'د':'d','ڈ':'d','ذ':'z','ر':'r','ڑ':'r','ز':'z','ژ':'zh','س':'s','ش':'sh','ص':'s','ض':'z','ط':'t','ظ':'z',
  'ع':'a','غ':'gh','ف':'f','ڤ':'v','ق':'q','ک':'k','گ':'g','ل':'l','م':'m','ن':'n','ں':'n','و':'w','ہ':'h','ھ':'h',
  'ء':'','ی':'y','ے':'e','ئ':'y','ؤ':'o','ۃ':'h','ۂ':'h','ـ':'','ً':'an','ٌ':'un','ٍ':'in','َ':'a','ُ':'u','ِ':'i','ّ':'',
  'ٓ':'','ٔ':'','ٕ':'','ٰ':'a'
};

function hasTargetScript(text) {
  return /[\u0900-\u097F\u0600-\u06FF\u0750-\u077F]/.test(text || '');
}

function normalizeDevanagari(text) {
  return text
    .replace(/क़/g, 'क़').replace(/ख़/g, 'ख़').replace(/ग़/g, 'ग़').replace(/ज़/g, 'ज़')
    .replace(/ड़/g, 'ड़').replace(/ढ़/g, 'ढ़').replace(/फ़/g, 'फ़').replace(/य़/g, 'य़');
}

function transliterateDevanagariWord(word) {
  const chars = [...normalizeDevanagari(word)];
  let out = '';

  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    const next = chars[i + 1];
    const pair = ch + (next || '');

    // Common nukta spellings such as क़, ख़, ग़, ज़, फ़.
    const nuktaMap = {
      'क़':'q','ख़':'kh','ग़':'gh','ज़':'z','ड़':'r','ढ़':'rh','फ़':'f','य़':'y'
    };
    if (nuktaMap[pair]) {
      out += nuktaMap[pair];
      i++;
      // Nukta consonants still take the normal inherent/matra handling.
      const after = chars[i + 1];
      if (DEV_MATRAS[after]) { out += DEV_MATRAS[after]; i++; }
      else if (after !== '्' && after && !DEV_CONSONANTS[after] && !DEV_VOWELS[after]) out += '';
      else if (after !== '्') out += 'a';
      continue;
    }

    if (DEV_VOWELS[ch]) {
      out += DEV_VOWELS[ch];
      continue;
    }

    if (DEV_SPECIAL[ch]) {
      out += DEV_SPECIAL[ch];
      continue;
    }

    if (ch === '्') continue;
    if (ch === '़') continue;
    if (DEV_MATRAS[ch]) {
      out += DEV_MATRAS[ch];
      continue;
    }

    if (DEV_CONSONANTS[ch]) {
      out += DEV_CONSONANTS[ch];
      if (next === '्') {
        // Virama explicitly suppresses the inherent vowel.
        continue;
      }
      if (!DEV_MATRAS[next]) {
        out += 'a';
      }
      continue;
    }

    out += ch;
  }

  // Hindi normally drops the inherent schwa at the end of many words.
  // This turns "phira" -> "phir", "hama" -> "ham", "aapa" -> "aap".
  out = out.replace(/a$/i, '');
  return out;
}

function transliterateDevanagari(text) {
  // Process whitespace-delimited words so final schwa deletion does not
  // accidentally affect the next word.
  return text.replace(/[^\s]+/g, transliterateDevanagariWord);
}

function transliterateUrdu(text) {
  // Urdu orthography often omits short vowels, so this remains intentionally
  // conservative; Latin text and punctuation are preserved.
  return [...text].map(ch => URDU[ch] ?? ch).join('');
}

function toRoman(text, mode = 'roman') {
  if (!text || mode !== 'roman' || !hasTargetScript(text)) return text || '';
  let output = transliterateDevanagari(text);
  output = transliterateUrdu(output);
  return output.replace(/[ \t]+/g, ' ').trim();
}


const STORAGE_KEYS = {
  RECORDING_STATE: 'recordingState',
  TRANSCRIPT: 'currentTranscript',
  INTERIM: 'interimTranscript',
  NOTE_TITLE: 'noteTitle',
  LAST_UPDATED: 'lastUpdated',
  ACTIVE_PROVIDER: 'activeProvider'
};

const DEFAULT_STATE = {
  isRecording: false,
  isPaused: false,
  startTime: null,
  pauseTime: null,
  totalPausedMs: 0,
  provider: null,
  captureMeetingAudio: false
};

const PROVIDERS = {
  deepgram: { label: 'Deepgram', kind: 'live' },
  assemblyai: { label: 'AssemblyAI', kind: 'live' },
  openai: { label: 'OpenAI', kind: 'chunked' }
};

async function getRecordingState() {
  const result = await chrome.storage.local.get(STORAGE_KEYS.RECORDING_STATE);
  return result[STORAGE_KEYS.RECORDING_STATE] || { ...DEFAULT_STATE };
}

async function setRecordingState(partial) {
  const current = await getRecordingState();
  const next = { ...current, ...partial };
  await chrome.storage.local.set({ [STORAGE_KEYS.RECORDING_STATE]: next });
  return next;
}

async function getTranscript() {
  const result = await chrome.storage.local.get(STORAGE_KEYS.TRANSCRIPT);
  return result[STORAGE_KEYS.TRANSCRIPT] || '';
}

async function setTranscript(text) {
  await chrome.storage.local.set({
    [STORAGE_KEYS.TRANSCRIPT]: text || '',
    [STORAGE_KEYS.LAST_UPDATED]: Date.now()
  });
}

async function getInterim() {
  const result = await chrome.storage.local.get(STORAGE_KEYS.INTERIM);
  return result[STORAGE_KEYS.INTERIM] || '';
}

async function setInterim(text) {
  await chrome.storage.local.set({ [STORAGE_KEYS.INTERIM]: text || '' });
}

async function clearNote() {
  await chrome.storage.local.set({
    [STORAGE_KEYS.TRANSCRIPT]: '',
    [STORAGE_KEYS.INTERIM]: '',
    [STORAGE_KEYS.NOTE_TITLE]: '',
    [STORAGE_KEYS.RECORDING_STATE]: { ...DEFAULT_STATE },
    [STORAGE_KEYS.LAST_UPDATED]: Date.now()
  });
}

async function getNoteSnapshot() {
  const result = await chrome.storage.local.get([
    STORAGE_KEYS.TRANSCRIPT,
    STORAGE_KEYS.INTERIM,
    STORAGE_KEYS.NOTE_TITLE,
    STORAGE_KEYS.RECORDING_STATE,
    STORAGE_KEYS.LAST_UPDATED
  ]);
  return {
    transcript: result[STORAGE_KEYS.TRANSCRIPT] || '',
    interim: result[STORAGE_KEYS.INTERIM] || '',
    noteTitle: result[STORAGE_KEYS.NOTE_TITLE] || '',
    recordingState: result[STORAGE_KEYS.RECORDING_STATE] || { ...DEFAULT_STATE },
    lastUpdated: result[STORAGE_KEYS.LAST_UPDATED] || null
  };
}

async function getActiveProviderOverride() {
  const result = await chrome.storage.local.get(STORAGE_KEYS.ACTIVE_PROVIDER);
  return result[STORAGE_KEYS.ACTIVE_PROVIDER] || null;
}

async function setActiveProviderOverride(provider) {
  if (provider && !PROVIDERS[provider]) throw new Error('Invalid provider');
  await chrome.storage.local.set({ [STORAGE_KEYS.ACTIVE_PROVIDER]: provider || '' });
}


const OFFSCREEN_URL = 'offscreen.html';
const OFFSCREEN_REASON = 'USER_MEDIA';
const OFFSCREEN_JUSTIFICATION = 'Continuous microphone capture for real-time AI transcription.';
const MEETING_COOLDOWN_MS = 30 * 60 * 1000;

let creating = null;
let bootResolver = null;

const MEETING_DETECTORS = [
  {
    name: 'Google Meet',
    test(url) {
      try {
        const u = new URL(url);
        return u.protocol === 'https:' && u.hostname === 'meet.google.com' && /^\/[a-z0-9]{3}-[a-z0-9]{4}-[a-z0-9]{3}(?:[/?#]|$)/i.test(u.pathname);
      } catch { return false; }
    }
  },
  {
    name: 'Zoom',
    test(url) {
      try {
        const u = new URL(url);
        if (!/^https?:$/.test(u.protocol) || !/(^|\.)zoom\.us$/i.test(u.hostname)) return false;
        return /^\/(?:j\/\d+|wc\/join\/|my\/|meeting\/)/i.test(u.pathname);
      } catch { return false; }
    }
  },
  {
    name: 'Microsoft Teams',
    test(url) {
      try {
        const u = new URL(url);
        if (!/^https?:$/.test(u.protocol)) return false;
        const host = u.hostname.toLowerCase();
        if (!(host === 'teams.microsoft.com' || host === 'teams.live.com' || host.endsWith('.teams.microsoft.com'))) return false;
        return /\/l\/meetup-join\//i.test(u.pathname + u.search);
      } catch { return false; }
    }
  }
];

function detectMeeting(url) {
  if (!url) return null;
  return MEETING_DETECTORS.find((detector) => detector.test(url)) || null;
}

async function hasOffscreenDocument() {
  const contexts = await chrome.runtime.getContexts({
    contextTypes: ['OFFSCREEN_DOCUMENT'],
    documentUrls: [chrome.runtime.getURL(OFFSCREEN_URL)]
  });
  return contexts.length > 0;
}

async function closeOffscreenDocument() {
  try {
    if (await hasOffscreenDocument()) await chrome.offscreen.closeDocument();
  } catch (err) {
    console.warn('[background] close offscreen:', err);
  }
}

async function ensureOffscreen() {
  await closeOffscreenDocument();
  if (creating) return creating;

  const boot = new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      bootResolver = null;
      reject(new Error('Transcription engine did not start in time'));
    }, 8000);
    bootResolver = () => {
      clearTimeout(timeout);
      bootResolver = null;
      resolve();
    };
  });

  creating = chrome.offscreen.createDocument({
    url: OFFSCREEN_URL,
    reasons: [OFFSCREEN_REASON],
    justification: OFFSCREEN_JUSTIFICATION
  }).then(() => boot).finally(() => { creating = null; });

  return creating;
}

async function sendToOffscreen(type, data = {}) {
  return chrome.runtime.sendMessage({ target: 'offscreen', type, data });
}

async function configuredProviders() {
  const config = globalThis.AI_NOTE_CONFIG || {};
  return (config.fallbackProviders || [config.activeProvider])
    .filter(name => config.keys?.[name]);
}

async function getMeetingState() {
  return chrome.storage.session.get({ pendingMeeting: null, meetingPromptHistory: {}, activeMeeting: null });
}

async function ensureUserId() {
  const { authUser, noteUserId } = await chrome.storage.local.get({ authUser: null, noteUserId: '' });
  if (authUser?.id) return authUser.id;
  if (noteUserId) return noteUserId;
  const id = crypto.randomUUID();
  await chrome.storage.local.set({ noteUserId: id });
  return id;
}

async function getAuthSession() {
  const { authToken, authApiKey, authUser } = await chrome.storage.local.get({
    authToken: '', authApiKey: '', authUser: null
  });
  const token = authApiKey || authToken || '';
  return { token, user: authUser || null, apiKey: authApiKey || '' };
}

async function setAuthSession({ token, user, apiKey }) {
  const key = apiKey || user?.apiKey || token || '';
  if (key && user) {
    await chrome.storage.local.set({
      authToken: token || key,
      authApiKey: key,
      authUser: user,
      noteUserId: user.id
    });
  } else if (key) {
    await chrome.storage.local.set({ authApiKey: key, authToken: key });
  } else {
    await chrome.storage.local.remove(['authToken', 'authApiKey', 'authUser']);
  }
}

async function requireAuthOrThrow() {
  const { authApiKey, authUser, authToken } = await chrome.storage.local.get({
    authApiKey: '', authUser: null, authToken: ''
  });
  const key = authApiKey || authToken || '';
  if (!key) {
    const err = new Error('Connect the extension with your API key from http://localhost:4000/account');
    err.code = 'AUTH_REQUIRED';
    throw err;
  }
  return { token: key, user: authUser, apiKey: key };
}

function getClientUrl() {
  // Web UI is served by the same backend (EJS) on :4000
  return String(globalThis.AI_NOTE_CONFIG?.backendUrl || 'http://localhost:4000').replace(/\/$/, '');
}

async function getBackendUrl() {
  const { backendUrlOverride } = await chrome.storage.local.get({ backendUrlOverride: '' });
  return String(backendUrlOverride || globalThis.AI_NOTE_CONFIG?.backendUrl || 'http://localhost:4000').replace(/\/$/, '');
}

async function postMeetingToBackend(payload) {
  const { token } = await requireAuthOrThrow();
  const response = await fetch(`${await getBackendUrl()}/api/meetings/complete`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`
    },
    body: JSON.stringify(payload)
  });
  const data = await response.json().catch(() => ({}));
  if (response.status === 401) {
    await setAuthSession({ token: '', user: null });
    throw new Error(data.error || 'Session expired. Please log in again.');
  }
  if (!response.ok || !data.ok) {
    throw new Error(data.error || data.analysisError || `Backend returned ${response.status}`);
  }
  return data;
}

async function enqueuePendingMeeting(payload, errorMessage) {
  const { pendingMeetingQueue = [] } = await chrome.storage.local.get({ pendingMeetingQueue: [] });
  const filtered = pendingMeetingQueue.filter((p) => p.externalId !== payload.externalId);
  filtered.push({ ...payload, queuedAt: Date.now(), lastError: errorMessage || '' });
  // Keep last 20
  await chrome.storage.local.set({
    pendingMeetingQueue: filtered.slice(-20),
    lastCompletedMeeting: payload,
    lastMeetingSyncError: { ok: false, error: errorMessage || 'Backend unavailable.', meetingId: payload.externalId }
  });
}

async function flushPendingMeetingQueue() {
  const { pendingMeetingQueue = [] } = await chrome.storage.local.get({ pendingMeetingQueue: [] });
  if (!pendingMeetingQueue.length) return { flushed: 0, remaining: 0 };

  const remaining = [];
  let flushed = 0;
  for (const item of pendingMeetingQueue) {
    try {
      await postMeetingToBackend(item);
      flushed += 1;
    } catch (err) {
      remaining.push({ ...item, lastError: err.message || String(err), queuedAt: item.queuedAt || Date.now() });
    }
  }
  await chrome.storage.local.set({ pendingMeetingQueue: remaining });
  if (!remaining.length) {
    await chrome.storage.local.remove(['lastCompletedMeeting', 'lastMeetingSyncError']);
  }
  return { flushed, remaining: remaining.length };
}

async function saveMeetingPayload(payload, { clearActiveMeeting = true } = {}) {
  await chrome.storage.local.set({ lastCompletedMeeting: payload });
  let sync = { ok: false, error: 'Backend unavailable.', meetingId: payload.externalId, analysisReady: false, analysisError: '' };
  try {
    const data = await postMeetingToBackend(payload);
    sync = {
      ok: true,
      meetingId: data.meeting?.externalId || payload.externalId,
      analysisReady: Boolean(data.analysisReady),
      analysisError: data.analysisError || ''
    };
    await chrome.storage.local.remove(['lastCompletedMeeting', 'lastMeetingSyncError']);
    // Also drop this id from any offline queue
    const { pendingMeetingQueue = [] } = await chrome.storage.local.get({ pendingMeetingQueue: [] });
    await chrome.storage.local.set({
      pendingMeetingQueue: pendingMeetingQueue.filter((p) => p.externalId !== payload.externalId)
    });
  } catch (error) {
    const msg = error.message || String(error);
    sync = { ok: false, error: msg, meetingId: payload.externalId, analysisReady: false, analysisError: msg };
    await enqueuePendingMeeting(payload, msg);
  }

  if (clearActiveMeeting) {
    await chrome.storage.session.remove('activeMeeting');
  }
  return { payload, sync };
}

async function saveCompletedMeeting() {
  const meetingState = await getMeetingState();
  const activeMeeting = meetingState.activeMeeting;
  const transcript = await getTranscript();
  const recordingState = await getRecordingState();
  const now = Date.now();
  const startedAt = activeMeeting?.startedAt || recordingState.startTime || now;
  const endedAt = now;
  const duration = Math.max(0, Math.round((endedAt - startedAt - (recordingState.totalPausedMs || 0)) / 1000));
  const titleResult = await chrome.storage.local.get({ noteTitle: 'Untitled meeting' });
  const payload = {
    externalId: activeMeeting?.id || crypto.randomUUID(),
    userId: await ensureUserId(),
    title: String(titleResult.noteTitle || activeMeeting?.title || 'Untitled meeting').slice(0, 160),
    platform: activeMeeting?.platform || 'Manual',
    meetingUrl: activeMeeting?.url || '',
    startedAt: new Date(startedAt).toISOString(),
    endedAt: new Date(endedAt).toISOString(),
    duration,
    participants: Array.isArray(activeMeeting?.participants) ? activeMeeting.participants : [],
    fullTranscript: transcript,
    transcript: transcript
      ? [{ speaker: 'Speaker', text: transcript, startTime: 0, endTime: duration, confidence: null }]
      : []
  };
  return saveMeetingPayload(payload, { clearActiveMeeting: true });
}

/** Save whatever is currently in the transcript (no recording required). */
async function saveAndAnalyzeFromText({ transcript, title, platform = 'Manual' } = {}) {
  const text = String(transcript || '').trim();
  if (!text) {
    throw new Error('Transcript is empty. Type or paste notes first.');
  }
  const now = Date.now();
  const payload = {
    externalId: crypto.randomUUID(),
    userId: await ensureUserId(),
    title: String(title || 'Untitled meeting').trim().slice(0, 160) || 'Untitled meeting',
    platform: String(platform || 'Manual').slice(0, 80),
    meetingUrl: '',
    startedAt: new Date(now).toISOString(),
    endedAt: new Date(now).toISOString(),
    duration: 0,
    participants: [],
    fullTranscript: text,
    transcript: [{ speaker: 'Speaker', text, startTime: 0, endTime: 0, confidence: null }]
  };
  // Persist local transcript so UI stays consistent
  await setTranscript(text);
  await chrome.storage.local.set({ noteTitle: payload.title, lastUpdated: Date.now() });
  return saveMeetingPayload(payload, { clearActiveMeeting: false });
}

async function stopActiveRecordingOnly(reason = 'manual-stop') {
  const recording = await getRecordingState();
  const { activeMeeting } = await getMeetingState();
  if (!recording?.isRecording) return { ok: true, alreadyStopped: true, reason };
  if (!activeMeeting?.id) {
    await setRecordingState({ isRecording: false, isPaused: false, startTime: null, pauseTime: null, totalPausedMs: 0, provider: null, captureMeetingAudio: false });
    try { await sendToOffscreen('OFFSCREEN_STOP'); } catch (_) {}
    await closeOffscreenDocument();
    return { ok: true, alreadyStopped: true, reason, error: 'No active meeting session.' };
  }
  try { await sendToOffscreen('OFFSCREEN_STOP'); } catch (err) {
    console.warn('[background] manual stop offscreen:', err?.message || err);
  }
  await new Promise(resolve => setTimeout(resolve, 500));
  await setRecordingState({ isRecording: false, isPaused: false, startTime: null, pauseTime: null, totalPausedMs: recording.totalPausedMs || 0, provider: null, captureMeetingAudio: false });
  await setInterim('');
  await closeOffscreenDocument();
  return { ok: true, stoppedOnly: true, reason, meetingId: activeMeeting.id };
}

async function saveStoppedMeeting() {
  if (activeStopPromise) return activeStopPromise;
  activeStopPromise = (async () => {
    const { activeMeeting } = await getMeetingState();
    if (!activeMeeting?.id) return { ok: false, error: 'There is no stopped meeting waiting to be saved.' };
    const processingId = activeMeeting.id;
    await chrome.storage.session.set({ meetingFinalizing: { id: processingId, startedAt: Date.now(), reason: 'manual-save' } });
    await openProcessingPage(processingId, activeMeeting.title || 'Meeting');
    const completed = await saveCompletedMeeting();
    await chrome.storage.session.remove('meetingFinalizing').catch(() => {});
    return {
      ok: true,
      meetingId: completed.sync.meetingId,
      synced: completed.sync.ok,
      syncError: completed.sync.error || '',
      analysisReady: completed.sync.analysisReady,
      analysisError: completed.sync.analysisError || ''
    };
  })().finally(async () => {
    await chrome.storage.session.remove('meetingFinalizing').catch(() => {});
    activeStopPromise = null;
  });
  return activeStopPromise;
}

let activeStopPromise = null;
let activeStartPromise = null;

/**
 * Finish the active meeting from any trigger (manual Stop, meeting UI End/Leave,
 * tab close, or navigation away). The promise guard prevents two end signals
 * from creating duplicate meetings/dashboards.
 */
async function finishActiveMeeting(reason = 'manual-stop') {
  if (activeStopPromise) return activeStopPromise;

  activeStopPromise = (async () => {
    const recording = await getRecordingState();
    if (!recording?.isRecording) {
      return { ok: true, alreadyStopped: true, reason };
    }
    const { activeMeeting } = await getMeetingState();
    if (!activeMeeting?.id) {
      await setRecordingState({ isRecording: false, isPaused: false, startTime: null, pauseTime: null, totalPausedMs: 0, provider: null });
      return { ok: true, alreadyStopped: true, reason, error: 'No active meeting session.' };
    }

    console.log(`[background] finishing meeting: ${reason}`);
    const processingId = activeMeeting.id;
    await chrome.storage.session.set({ meetingFinalizing: { id: processingId, startedAt: Date.now(), reason } });
    // Open a Tactiq-style processing page immediately. It polls the backend
    // until the finalized meeting (including AI analysis) is available.
    await openProcessingPage(processingId, activeMeeting.title || 'Meeting');
    try { await sendToOffscreen('OFFSCREEN_STOP'); } catch (err) {
      console.warn('[background] offscreen stop:', err?.message || err);
    }

    // Give the provider a short window to deliver final transcript events.
    await new Promise(resolve => setTimeout(resolve, 900));

    const completed = await saveCompletedMeeting();
    await setRecordingState({
      isRecording: false,
      isPaused: false,
      startTime: null,
      pauseTime: null,
      totalPausedMs: 0,
      provider: null
    });
    await setInterim('');
    await closeOffscreenDocument();

    try {
      const tabs = await chrome.tabs.query({});
      for (const tab of tabs) {
        if (tab.id) await chrome.action.setBadgeText({ tabId: tab.id, text: '' }).catch(() => {});
      }
    } catch {}

    const result = {
      ok: true,
      reason,
      meetingId: completed.sync.meetingId,
      synced: completed.sync.ok,
      syncError: completed.sync.error || '',
      analysisReady: completed.sync.analysisReady,
      analysisError: completed.sync.analysisError || ''
    };

    // The processing page opened above will redirect itself to the finished
    // meeting once /api/meetings/complete has saved and analyzed it.
    await chrome.storage.session.remove('meetingFinalizing');
    return result;
  })().finally(async () => {
    await chrome.storage.session.remove('meetingFinalizing').catch(() => {});
    activeStopPromise = null;
  });

  return activeStopPromise;
}

async function openProcessingPage(meetingId, title = 'Meeting') {
  const base = String(globalThis.AI_NOTE_CONFIG?.backendUrl || 'http://localhost:4000').replace(/\/$/, '');
  const params = new URLSearchParams({ title: String(title || 'Meeting').slice(0, 160) });
  const url = `${base}/meetings/processing/${encodeURIComponent(meetingId)}?${params.toString()}`;
  try {
    await chrome.tabs.create({ url, active: true });
  } catch (error) {
    console.warn('[background] processing page open failed:', error);
  }
}

async function openDashboard(meetingId = '') {
  // Prefer the EJS web dashboard on the API server so the user sees summary/chat there
  const base = String(globalThis.AI_NOTE_CONFIG?.backendUrl || 'http://localhost:4000').replace(/\/$/, '');
  const url = meetingId
    ? `${base}/meetings/${encodeURIComponent(meetingId)}`
    : `${base}/`;
  try {
    await chrome.tabs.create({ url });
  } catch (error) {
    console.warn('[background] web dashboard open failed, falling back to extension page:', error);
    try {
      const fallback = chrome.runtime.getURL(`dashboard.html${meetingId ? `?meeting=${encodeURIComponent(meetingId)}` : ''}`);
      await chrome.tabs.create({ url: fallback });
    } catch (e2) {
      console.warn('[background] dashboard open failed:', e2);
    }
  }
}

// Periodic offline queue flush (every 2 minutes when the service worker is alive)
chrome.alarms?.create?.('flushPendingMeetings', { periodInMinutes: 2 });
chrome.alarms?.onAlarm?.addListener?.(async (alarm) => {
  if (alarm.name === 'flushPendingMeetings') {
    try {
      const result = await flushPendingMeetingQueue();
      if (result.flushed) console.log('[background] flushed pending meetings:', result);
    } catch (err) {
      console.warn('[background] queue flush failed:', err);
    }
  }
});

async function markMeetingDetected(tabId, url) {
  const key = `${tabId}:${url}`;
  const state = await getMeetingState();
  const history = { ...(state.meetingPromptHistory || {}) };
  history[key] = Date.now();
  const cutoff = Date.now() - MEETING_COOLDOWN_MS;
  for (const [entry, timestamp] of Object.entries(history)) {
    if (timestamp < cutoff) delete history[entry];
  }
  await chrome.storage.session.set({ meetingPromptHistory: history });
}

async function wasMeetingRecentlyDetected(tabId, url) {
  const state = await getMeetingState();
  const timestamp = state.meetingPromptHistory?.[`${tabId}:${url}`];
  return Boolean(timestamp && Date.now() - timestamp < MEETING_COOLDOWN_MS);
}

async function startRecordingInternal({ automatic = false, tabCaptureStreamId = null, captureMeetingAudio = false } = {}) {
  if (activeStartPromise) return activeStartPromise;
  activeStartPromise = (async () => {
  const { meetingFinalizing } = await chrome.storage.session.get({ meetingFinalizing: null });
  if (meetingFinalizing?.id && Date.now() - Number(meetingFinalizing.startedAt || 0) < 10 * 60 * 1000) {
    throw new Error('A previous meeting is still being finalized.');
  }
  if (meetingFinalizing?.id) await chrome.storage.session.remove('meetingFinalizing');
  const providers = await configuredProviders();
  if (!providers.length) {
    throw new Error('No transcription provider is configured. Add developer API keys to .env and run npm run build.');
  }

  const meetingState = await getMeetingState();
  let activeMeeting = meetingState.activeMeeting;
  if (!activeMeeting) {
    const pending = meetingState.pendingMeeting;
    let activeTab = null;
    if (!pending) {
      try { [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true }); } catch {}
    }
    activeMeeting = {
      id: crypto.randomUUID(),
      platform: pending?.platform || detectMeeting(activeTab?.url)?.name || 'Manual',
      url: pending?.url || activeTab?.url || '',
      title: pending?.title || activeTab?.title || 'Untitled meeting',
      tabId: pending?.tabId || activeTab?.id || null,
      startedAt: Date.now(),
      participants: []
    };
    await chrome.storage.session.set({ activeMeeting });
  }

  await ensureOffscreen();
  await setInterim('');
  await chrome.storage.local.set({ noteTitle: activeMeeting.title || 'Untitled meeting' });
  await setRecordingState({
    isRecording: true, isPaused: false, startTime: Date.now(),
    pauseTime: null, totalPausedMs: 0, provider: null, captureMeetingAudio: Boolean(captureMeetingAudio)
  });

  const result = await sendToOffscreen('OFFSCREEN_START', {
    tabCaptureStreamId: tabCaptureStreamId || null,
    captureMeetingAudio: Boolean(captureMeetingAudio && tabCaptureStreamId)
  });
  if (!result?.ok) {
    await setRecordingState({ isRecording: false, isPaused: false, provider: null });
    await closeOffscreenDocument();
    throw new Error(result?.error || 'Unable to start transcription');
  }

  const finalState = await setRecordingState({ provider: result.provider || null });
  if (automatic) console.log('[background] Automatic meeting transcription started:', finalState.provider);
  return finalState;
  })().finally(() => { activeStartPromise = null; });
  return activeStartPromise;
}

async function showTranscribingPopup(meeting, { permissionRequired = false, error = '' } = {}) {
  const params = new URLSearchParams({
    platform: meeting?.platform || 'Meeting',
    url: meeting?.url || '',
    state: permissionRequired ? 'permission' : (error ? 'error' : 'started')
  });
  if (error) params.set('error', error.slice(0, 240));

  try {
    const popup = await chrome.windows.create({
      url: chrome.runtime.getURL(`transcribing.html?${params.toString()}`),
      type: 'popup',
      width: 500,
      height: permissionRequired ? 280 : 210,
      focused: true
    });

    // The popup is intentionally short-lived. The transcription itself lives
    // in the offscreen document and is not tied to this window.
    if (popup?.id) {
      setTimeout(() => {
        chrome.windows.remove(popup.id).catch(() => {});
      }, 5000);
    }
  } catch (err) {
    console.warn('[background] unable to show transcription popup:', err);
  }
}

async function tryGetMeetingAudioStreamId(tab) {
  if (!tab?.id || !detectMeeting(tab.url)) return null;

  // Remote/tab audio is best-effort only. This function must be called from
  // an explicit user invocation context (for example, the extension action
  // while the meeting tab is the active tab). Automatic URL detection must
  // never call it because activeTab is not granted by URL detection.
  try {
    const streamId = await chrome.tabCapture.getMediaStreamId({
      targetTabId: tab.id
    });
    return streamId || null;
  } catch (err) {
    console.info('[background] meeting-audio capture unavailable; continuing with microphone:', err?.message || err);
    return null;
  }
}

async function openExtensionPopup(tab) {
  if (!tab?.id || !tab?.windowId || !tab.url) return;
  const detector = detectMeeting(tab.url);
  if (!detector) return;

  const recording = await getRecordingState();
  if (recording?.isRecording) return;
  if (await wasMeetingRecentlyDetected(tab.id, tab.url)) return;

  const pendingMeeting = {
    platform: detector.name,
    url: tab.url,
    tabId: tab.id,
    windowId: tab.windowId,
    detectedAt: Date.now()
  };

  await chrome.storage.session.set({ pendingMeeting });
  await markMeetingDetected(tab.id, tab.url);

  // Automatic detection starts microphone transcription without attempting
  // tabCapture. Chrome's tabCapture API requires a user invocation on the
  // target tab; URL detection alone cannot grant that permission. This keeps
  // automatic transcription reliable even when the user is working in any
  // other tab. Remote meeting audio is enabled through the explicit/manual
  // capture path when Chrome has granted the required tab-capture context.
  try {
    const finalState = await startRecordingInternal({
      automatic: true,
      tabCaptureStreamId: null,
      captureMeetingAudio: false
    });

    await chrome.storage.session.remove('pendingMeeting');
    await showTranscribingPopup(pendingMeeting);
    try { await chrome.action.setBadgeText({ tabId: tab.id, text: 'REC' }); } catch {}
    try { await chrome.action.setBadgeBackgroundColor({ tabId: tab.id, color: '#ef4444' }); } catch {}
    console.log('[background] Meeting transcription active:', finalState.provider, pendingMeeting.platform);
  } catch (err) {
    await chrome.storage.session.remove('pendingMeeting');
    const message = err?.message || String(err);
    const permissionRequired = /notallowed|permission|microphone|user.?media/i.test(message);
    await showTranscribingPopup(pendingMeeting, { permissionRequired, error: message });

    if (permissionRequired) {
      // Give the user a normal extension page where Chrome can present the
      // microphone permission UI. We do not silently retry in a loop.
      try {
        if (typeof chrome.action?.openPopup === 'function') {
          await chrome.action.openPopup({ windowId: tab.windowId });
        }
      } catch (openErr) {
        console.warn('[background] permission popup could not be opened:', openErr);
      }
    }
    console.warn('[background] automatic meeting transcription failed:', message);
  }
}
async function scanTabs() {
  try {
    const tabs = await chrome.tabs.query({});
    for (const tab of tabs) {
      if (detectMeeting(tab.url)) {
        await openExtensionPopup(tab);
        break;
      }
    }
  } catch (err) {
    console.warn('[background] tab scan:', err);
  }
}

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.url) {
    getMeetingState().then(async ({ activeMeeting }) => {
      const recording = await getRecordingState();
      if (recording?.isRecording && activeMeeting?.tabId === tabId && !detectMeeting(changeInfo.url)) {
        await finishActiveMeeting('meeting-tab-navigated-away');
      }
    }).catch(err => console.warn('[background] meeting navigation check:', err));
  }

  if (changeInfo.status === 'complete' && detectMeeting(tab.url)) {
    openExtensionPopup(tab).catch(err => console.warn('[background] detect:', err));
  }
});

chrome.tabs.onRemoved.addListener((tabId) => {
  getMeetingState().then(async ({ activeMeeting }) => {
    const recording = await getRecordingState();
    if (recording?.isRecording && activeMeeting?.tabId === tabId) {
      await finishActiveMeeting('meeting-tab-closed');
    }
  }).catch(err => console.warn('[background] meeting tab close check:', err));
});

chrome.tabs.onActivated.addListener(async ({ tabId }) => {
  try {
    const tab = await chrome.tabs.get(tabId);
    if (detectMeeting(tab.url)) await openExtensionPopup(tab);
  } catch (err) {
    console.warn('[background] activation detect:', err);
  }
});

chrome.runtime.onInstalled.addListener(async () => {
  scanTabs();
  try {
    const { onboardingCompleted } = await chrome.storage.local.get({ onboardingCompleted: false });
    if (!onboardingCompleted) await chrome.tabs.create({ url: chrome.runtime.getURL('onboarding.html') });
  } catch (error) { console.warn('[background] onboarding:', error); }
});
chrome.runtime.onStartup.addListener(() => { scanTabs(); });

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.target && message.target !== 'background') return false;

  (async () => {
    try {
      switch (message.type) {
        case 'GET_STATE': {
          const snapshot = await getNoteSnapshot();
          const providers = await configuredProviders();
          const meetingState = await getMeetingState();
          const auth = await getAuthSession();
          sendResponse({
            ok: true, ...snapshot,
            pendingMeeting: meetingState.pendingMeeting || null,
            activeMeeting: meetingState.activeMeeting || null,
            activeProvider: globalThis.AI_NOTE_CONFIG?.activeProvider || 'assemblyai',
            configuredProviders: providers,
            authUser: auth.user,
            isLoggedIn: Boolean(auth.token),
            backendUrl: await getBackendUrl()
          });
          break;
        }

        case 'GET_AUTH': {
          const auth = await getAuthSession();
          sendResponse({ ok: true, user: auth.user, isLoggedIn: Boolean(auth.token), clientUrl: getClientUrl() });
          break;
        }

        case 'AUTH_LOGIN': {
          try {
            const response = await fetch(`${await getBackendUrl()}/api/auth/login`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                username: message.username,
                passkey: message.passkey,
                label: 'extension'
              })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.ok) throw new Error(data.error || 'Login failed');
            await setAuthSession({ token: data.token, user: data.user, apiKey: data.apiKey || data.user?.apiKey });
            sendResponse({ ok: true, user: data.user, apiKey: data.apiKey || data.user?.apiKey });
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'AUTH_REGISTER': {
          try {
            const response = await fetch(`${await getBackendUrl()}/api/auth/register`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                username: message.username,
                passkey: message.passkey,
                displayName: message.displayName || ''
              })
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.ok) throw new Error(data.error || 'Register failed');
            await setAuthSession({ token: data.token, user: data.user, apiKey: data.apiKey || data.user?.apiKey });
            sendResponse({ ok: true, user: data.user, apiKey: data.apiKey || data.user?.apiKey });
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'AUTH_LOGOUT': {
          try {
            const { token } = await getAuthSession();
            if (token) {
              await fetch(`${await getBackendUrl()}/api/auth/logout`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                body: JSON.stringify({ token })
              }).catch(() => {});
            }
          } catch (_) {}
          await setAuthSession({ token: '', user: null });
          sendResponse({ ok: true });
          break;
        }

        case 'OPEN_CLIENT_AUTH': {
          const url = `${getClientUrl()}/register`;
          try {
            await chrome.tabs.create({ url });
            sendResponse({ ok: true, url });
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'START_RECORDING': {
          try {
            const finalState = await startRecordingInternal({
              automatic: false,
              tabCaptureStreamId: message.tabCaptureStreamId || null,
              captureMeetingAudio: Boolean(message.captureMeetingAudio)
            });
            sendResponse({ ok: true, state: finalState });
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'STOP_RECORDING': {
          const result = await stopActiveRecordingOnly('manual-stop');
          sendResponse(result);
          break;
        }

        case 'SAVE_STOPPED_MEETING': {
          try {
            const result = await saveStoppedMeeting();
            sendResponse(result);
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'MEETING_PARTICIPANTS_UPDATE': {
          const meetingState = await getMeetingState();
          const activeMeeting = meetingState.activeMeeting;
          if (!activeMeeting) {
            sendResponse({ ok: true, ignored: true });
            break;
          }
          if (Number.isInteger(sender?.tab?.id) && Number.isInteger(activeMeeting.tabId) && sender.tab.id !== activeMeeting.tabId) {
            sendResponse({ ok: true, ignored: true });
            break;
          }
          const incoming = Array.isArray(message.participants) ? message.participants : [];
          const existing = Array.isArray(activeMeeting.participants) ? activeMeeting.participants : [];
          const merged = new Map();
          for (const p of [...existing, ...incoming]) {
            const name = String(p?.name || p?.displayName || '').replace(/\s+/g, ' ').trim();
            if (!name || name.length > 100) continue;
            const key = name.toLowerCase();
            if (!merged.has(key)) merged.set(key, { name, email: String(p?.email || '') });
          }
          activeMeeting.participants = Array.from(merged.values()).slice(0, 50);
          await chrome.storage.session.set({ activeMeeting });
          sendResponse({ ok: true, participants: activeMeeting.participants });
          break;
        }

        case 'MEETING_ENDED_BY_USER': {
          const meetingState = await getMeetingState();
          const activeMeeting = meetingState.activeMeeting;
          const recording = await getRecordingState();
          if (!recording?.isRecording || !activeMeeting) {
            sendResponse({ ok: true, ignored: true });
            break;
          }
          if (Number.isInteger(sender?.tab?.id) && Number.isInteger(activeMeeting.tabId) && sender.tab.id !== activeMeeting.tabId) {
            sendResponse({ ok: true, ignored: true });
            break;
          }
          const result = await finishActiveMeeting(message.reason || 'meeting-end-control');
          sendResponse(result);
          break;
        }

        case 'SAVE_AND_ANALYZE': {
          try {
            const completed = await saveAndAnalyzeFromText({
              transcript: message.transcript,
              title: message.title,
              platform: message.platform || 'Manual'
            });
            sendResponse({
              ok: true,
              meetingId: completed.sync.meetingId,
              synced: completed.sync.ok,
              syncError: completed.sync.error || '',
              analysisReady: completed.sync.analysisReady,
              analysisError: completed.sync.analysisError || ''
            });
            await openDashboard(completed.sync.meetingId || completed.payload.externalId);
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'SET_API_KEY': {
          try {
            const apiKey = String(message.apiKey || '').trim();
            const serverUrl = String(message.serverUrl || '').trim().replace(/\/$/, '') || 'http://localhost:4000';
            if (!apiKey) throw new Error('API key is required');
            await chrome.storage.local.set({ backendUrlOverride: serverUrl });
            // Validate key against server
            const response = await fetch(`${serverUrl}/api/auth/me`, {
              headers: { Authorization: `Bearer ${apiKey}`, 'X-API-Key': apiKey }
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.ok) throw new Error(data.error || 'Invalid API key');
            await setAuthSession({ token: apiKey, user: data.user, apiKey });
            sendResponse({ ok: true, user: data.user });
          } catch (err) {
            sendResponse({ ok: false, error: err.message || String(err) });
          }
          break;
        }

        case 'FLUSH_PENDING_MEETINGS': {
          const result = await flushPendingMeetingQueue();
          sendResponse({ ok: true, ...result });
          break;
        }

        case 'PAUSE_RECORDING':
          await sendToOffscreen('OFFSCREEN_PAUSE');
          await setRecordingState({ isPaused: true, pauseTime: Date.now() });
          sendResponse({ ok: true });
          break;

        case 'RESUME_RECORDING': {
          const current = await getRecordingState();
          let totalPausedMs = current.totalPausedMs || 0;
          if (current.pauseTime) totalPausedMs += Date.now() - current.pauseTime;
          await sendToOffscreen('OFFSCREEN_RESUME');
          await setRecordingState({ isPaused: false, pauseTime: null, totalPausedMs });
          sendResponse({ ok: true });
          break;
        }

        case 'NEW_NOTE': {
          const state = await getRecordingState();
          if (state.isRecording) {
            try { await sendToOffscreen('OFFSCREEN_STOP'); } catch {}
            await closeOffscreenDocument();
          }
          await clearNote();
          sendResponse({ ok: true });
          break;
        }

        case 'SET_TITLE': {
          const title = String(message.title || '').trim().slice(0, 120) || 'Untitled meeting';
          await chrome.storage.local.set({ noteTitle: title, lastUpdated: Date.now() });
          sendResponse({ ok: true, title });
          break;
        }

        case 'CLEAR_NOTE':
          await setTranscript('');
          await setInterim('');
          sendResponse({ ok: true });
          break;

        case 'TRANSCRIPT_UPDATE': {
          const result = await chrome.storage.local.get({ transcriptScript: 'roman' });
          const scriptMode = result.transcriptScript || 'roman';
          const addition = toRoman((message.transcript || '').trim(), scriptMode).trim();
          if (!addition) { sendResponse({ ok: true }); break; }
          if (message.is_final) {
            const existing = await getTranscript();
            const separator = existing && !/[ \n]$/.test(existing) ? ' ' : '';
            await setTranscript(existing + separator + addition);
            await setInterim('');
          } else {
            await setInterim(addition);
          }
          sendResponse({ ok: true });
          break;
        }

        case 'OFFSCREEN_ERROR':
          await setRecordingState({ isRecording: false, isPaused: false });
          await setInterim('');
          sendResponse({ ok: true, error: message.error });
          break;

        case 'OFFSCREEN_BOOTED':
          bootResolver?.();
          sendResponse({ ok: true });
          break;

        case 'OFFSCREEN_READY':
          await setRecordingState({ provider: message.provider || null });
          sendResponse({ ok: true });
          break;

        case 'DISMISS_MEETING_PROMPT':
          await chrome.storage.session.remove('pendingMeeting');
          sendResponse({ ok: true });
          break;

        case 'MEETING_TRANSCRIPTION_STARTED': {
          const meetingState = await getMeetingState();
          const meeting = meetingState.pendingMeeting;
          if (Number.isInteger(message.tabId)) {
            try { await chrome.tabs.update(message.tabId, { active: true }); } catch {}
          } else if (Number.isInteger(meeting?.tabId)) {
            try { await chrome.tabs.update(meeting.tabId, { active: true }); } catch {}
          }
          await chrome.storage.session.remove('pendingMeeting');
          sendResponse({ ok: true });
          break;
        }

        default:
          sendResponse({ ok: false, error: 'Unknown message type' });
      }
    } catch (err) {
      console.error('[background] error:', err);
      sendResponse({ ok: false, error: err.message || String(err) });
    }
  })();
  return true;
});

